const body = $input.first()?.json?.body || $input.first()?.json || {};
const data = body.data || body;
const key = data.key || body.key || {};

const fromMe = key.fromMe === true;
const remoteJid = key.remoteJid || '';

if (remoteJid.includes('@g.us') || remoteJid.includes('broadcast') || remoteJid.includes('@newsletter')) {
  return [];
}

const rawNumber = remoteJid ? remoteJid.split('@')[0] : (key.participant || '').split('@')[0];
const cleanPhone = rawNumber ? rawNumber.replace(/\D/g, '') : '';
if (!cleanPhone) {
  return [];
}

const msgObj = data.message || body.message || {};
let text = '';
let messageType = 'texto';

if (data.messageType === 'conversation' || msgObj.conversation) {
  text = msgObj.conversation || '';
} else if (data.messageType === 'extendedTextMessage' || msgObj.extendedTextMessage) {
  text = msgObj.extendedTextMessage?.text || '';
} else if (data.messageType === 'audioMessage' || msgObj.audioMessage) {
  messageType = 'voz';
}

const pushName = data.pushName || body.pushName || 'Parceiro';
const primeiroNome = pushName.split(' ')[0] || 'Parceiro';
const comando = text.trim().toLowerCase();
const isComandoReativar = comando === '#ia' || comando === '#ativar' || comando === 'ativar ia';

return [{
  json: {
    fromMe,
    isComandoReativar,
    instanceName: 'meutim',
    tipo: messageType,
    telefone: cleanPhone,
    pushName,
    primeiroNome,
    mensagem: text.trim(),
    mimetype: msgObj.audioMessage?.mimetype || 'audio/ogg',
    base64: '',
    rawMessage: msgObj,
    messageId: key.id || String(Date.now()),
    timestamp: Date.now()
  }
}];

const prevData = $('Normalizar Dados').first()?.json || {};
const item = $input.first()?.json || {};

const base64Data = item.base64 || item.data?.base64 || prevData.base64 || '';
const mimeType = item.mimetype || item.data?.mimetype || 'audio/ogg';

const binaryData = {
  data: base64Data,
  mimeType: mimeType,
  fileName: 'audio.ogg'
};

return [{
  json: {
    ...prevData,
    base64Loaded: Boolean(base64Data)
  },
  binary: {
    file: binaryData,
    data: binaryData
  }
}];

const prevData = $('Normalizar Dados').first()?.json || {};
const whisperResult = $input.first()?.json || {};

const transcrito = whisperResult.text ? String(whisperResult.text).trim() : '';
const textoFinal = transcrito.length > 0 ? transcrito : '[Mensagem de áudio]';

return [{
  json: {
    ...prevData,
    mensagem: textoFinal,
    transcricaoVoz: transcrito,
    isAudioTranscribed: true
  }
}];

let current = '';
let info = $('Normalizar Dados').first()?.json || {};

try {
  const voz = $('Definir Mensagem Transcrita').first()?.json;
  if (voz && voz.mensagem) {
    info = voz;
    current = voz.mensagem;
  }
} catch (e) {}

if (!current) {
  current = info.mensagem || '';
}

const prev = $input.first()?.json?.propertyName ?? $input.first()?.json?.value ?? '';
const combined = (prev && typeof prev === 'string' && prev.trim().length > 0)
  ? `${prev.trim()} ${current.trim()}`
  : current.trim();

return [{
  json: {
    ...info,
    mensagemBuffer: combined
  }
}];

const bufferContent = $input.first()?.json?.propertyName || '';
let fallback = '';
let pushName = 'Parceiro';
let primeiroNome = 'Parceiro';

try {
  const norm = $('Normalizar Dados').first()?.json;
  if (norm) {
    fallback = norm.mensagem || '';
    pushName = norm.pushName || 'Parceiro';
    primeiroNome = norm.primeiroNome || 'Parceiro';
  }
} catch (e) {}

const mensagemCompleta = (bufferContent && bufferContent.trim().length > 0)
  ? bufferContent.trim()
  : fallback.trim();

return [{
  json: {
    instance: 'meutim',
    telefone: $('Normalizar Dados').item.json.telefone,
    pushName,
    primeiroNome,
    mensagemCompleta
  }
}];

const agentOutput = $input.first().json.output || $input.first().json.text || '';
const hotelInfo = $('Agrupar Mensagens em Uma').first().json;
const textoRecebido = (hotelInfo.mensagemCompleta || '').toLowerCase();

// Detecta se é lead quente ou se o link foi enviado
const contemLink = agentOutput.includes('hotelnozap.com.br');
const pediuPrecoOuLink = textoRecebido.includes('preço') ||
  textoRecebido.includes('preco') ||
  textoRecebido.includes('valor') ||
  textoRecebido.includes('quanto custa') ||
  textoRecebido.includes('como funciona') ||
  textoRecebido.includes('link') ||
  textoRecebido.includes('quero testar') ||
  textoRecebido.includes('cadastro');

const leadQuente = contemLink || pediuPrecoOuLink;

const mensagemAlertaEveraldo = `🚨 *LEAD QUENTE - HOTEL NO ZAP!*\n\n📱 *Lead:* ${hotelInfo.pushName} (${hotelInfo.telefone})\n💬 *Disse:* "${hotelInfo.mensagemCompleta}"\n🎯 *Status:* ${contemLink ? 'Link da LP enviado pela IA!' : 'Demonstrou interesse comercial!'}\n\n👉 *Falar com ele no WhatsApp:*\nhttps://wa.me/${hotelInfo.telefone}`;

return [{
  json: {
    telefone: hotelInfo.telefone,
    pushName: hotelInfo.pushName,
    primeiroNome: hotelInfo.primeiroNome,
    resposta: agentOutput.trim(),
    leadQuente,
    mensagemAlertaEveraldo,
    adminWhatsapp: '5565996173004'
  }
}];

const isBot = Boolean($input.first()?.json?.propertyName);
const norm = $('Normalizar Dados').first()?.json || {};
if (isBot) {
  return []; // Eco do envio do próprio robô
}
return [{
  json: {
    ...norm,
    isEveraldo: true
  }
}];

const pausa = $input.first()?.json?.propertyName ?? null;
const original = $('Normalizar Dados').first()?.json || {};

return [{
